"""Thesis-ready narrative and completion report derived from measured final artifacts."""
import json,shutil,statistics
from pathlib import Path
ROOT=Path('results/final/smollm2_v1');SNAP=Path('experiments/final_smollm2_v1')
def fmt(v):return 'N/A' if v['mean'] is None else f'{100*v["mean"]:.3f}% ± {100*(v["std"] or 0):.3f}'
def main():
 aggregate=json.loads((ROOT/'aggregate.json').read_text());claims=json.loads((ROOT/'claims.json').read_text());ab=json.loads((ROOT/'ablations.json').read_text())['measured'];cost=json.loads((ROOT/'costs.json').read_text());errors=json.loads((ROOT/'failure_taxonomy.json').read_text());audit=json.loads((ROOT/'fairness_audit.json').read_text());stats=json.loads((ROOT/'statistics.json').read_text());coverage=json.loads((ROOT/'holdout_coverage.json').read_text());history=json.loads(Path('results/final/historical_mlp_v1/aggregate.json').read_text());references=json.loads(Path('results/final/references_v1/references.json').read_text())
 names={'answer_only':'Answer-only A','structured':'Structured baseline','trajectory':'Mindscape B','experiential':'Mindscape C'}
 lines=['# Final results','', 'Final main study:90 adapted heads (84 primary plus6 retrained ablations),210 shared-runner evaluations, three seeds0/1/2,200 IID and300 OOD examples per run. An additional12 historical MLP models/24 evaluations and6 non-neural reference evaluations use the same fresh final dataset. Total final research evaluations240;102 trained research models. Diagnostics are separate. Raw results remain in `results/final/`; the committed summary snapshot is `experiments/final_smollm2_v1/`.','', '## Primary results at1000 training problems','', '| Condition | IID exact accuracy | Structural OOD exact accuracy | IID groundedness | IID goal success | IID trajectory validity |','|---|---:|---:|---:|---:|---:|']
 for c in names:
  t=next(r for r in aggregate if r['condition']==c and r['budget']==1000 and r['split']=='test');o=next(r for r in aggregate if r['condition']==c and r['budget']==1000 and r['split']=='ood_test');lines.append('|'+names[c]+'|'+'|'.join([fmt(t['accuracy']),fmt(o['accuracy']),fmt(t['grounded_rate']),fmt(t['goal_success_rate']),fmt(t['trajectory_validity'])])+'|')
 lines+=['','All rates are mean±sample SD across three training seeds. A/structured do not emit trajectories; validity isN/A and their evidence-required grounding/goal scores are0 by protocol. B OOD groundedness/goal/validity are6.111%±1.347; C OOD rates are0. No final success target was met.','', '## Learning curves','']
 for split in ['test','ood_test']:
  lines+=['### '+('IID' if split=='test' else 'Structural OOD'),'','| Training problems | Answer-only A | Structured | B | C |','|---:|---:|---:|---:|---:|']
  for budget in [10,25,50,100,250,500,1000]:lines.append('|'+str(budget)+'|'+'|'.join(fmt(next(r for r in aggregate if r['condition']==c and r['budget']==budget and r['split']==split)['accuracy']) for c in names)+'|')
 lines+=['','## Data efficiency and costs','', 'All observed N*(0.8/0.9/0.95) thresholds were not reached on either split for every condition; all DERs are censored/not reached. There is no measured2× or5× threshold-crossing advantage. Problem budget is distinct from label, feedback-query and compute budget.','',f'Main study measured training time{cost["totals"]["training_seconds"]:.3f}s and evaluation time{cost["totals"]["evaluation_seconds"]:.3f}s. It performed{cost["totals"]["gradient_steps"]:,} optimizer updates,{cost["totals"]["sampled_supervision_rows"]:,} sampled supervision rows,{cost["totals"]["feedback_queries"]:,} scalar feedback queries and{cost["totals"]["prediction_head_calls"]:,} prediction-head calls. The shared frozen transformer processed{cost["shared_encoder"]["unique_transformer_input_tokens"]:,} tokens in{cost["shared_encoder"]["unique_transformer_batches"]:,} batches; encoder feature requests{cost["shared_encoder"]["feature_requests"]:,}. These are cached CPU measurements, exclude dataset/artifact bookkeeping outside timed sections, and do not establish cold-deployment compute efficiency. Full per-model costs are in `costs.json`.','', '## Ablations at50 problems','', '| Intervention | IID Δaccuracy (pp) | OOD Δaccuracy (pp) | IID Δgroundedness (pp) | IID Δgoal (pp) |','|---|---:|---:|---:|---:|']
 for variant in sorted({r['variant'] for r in ab}):
  t=next(r for r in ab if r['variant']==variant and r['split']=='test');o=next(r for r in ab if r['variant']==variant and r['split']=='ood_test');lines.append(f'|{variant}|{100*t["delta_accuracy"]:.3f}|{100*o["delta_accuracy"]:.3f}|{100*t["delta_grounded_rate"]:.3f}|{100*t["delta_goal_success_rate"]:.3f}|')
 lines+=['','Every intervention has three seeds. Δdata efficiency is not estimable from one budget. No goal evaluator means removal of a constant goal input flag while retaining common external scoring. C versus B is a supervision/feedback contrast, not an isolated removal. No real interaction preserves numerical predictions but loses real evidence by definition. The matched local supervised policy and matched-order/update no-SQLite-retrieval control have identical predictions to their references. Dream changed no measured accuracy/groundedness/goal; its extra calls do not support usefulness. The no-state mean reduction is not significant in every seed after the component-test Holm family, so state-contribution claims remain inconclusive at this budget.','', '## Statistics and errors','', 'Per-run Wilson95 intervals report conditional example uncertainty; seed SD reports training variation. Exploratory paired tests use seed0 at1000, six Holm comparisons; component tests are a separate18-comparison family across seeds/splits. No seed pooling. B versus A IID Holm p=2.2354e-17 and OOD p=1.90735e-6; C versus A IID p=1.80444e-7. These differences are observed regime associations, not controls for the unequal information/scaffold. Practical OOD performance remains6.11%, far below90%.','', '| Failure/outcome category | Count across210 repeated-set evaluations |','|---|---:|']
 lines += [f'|{k}|{v}|' for k,v in errors.items()]
 lines+=['','These counts describe repeated benchmark runs, not unique independent errors. `difficulty_failures.json` groups condition/budget/seed/IID-OOD/digit structure/carry count, and per-run `failures.json` retains example identities and original taxonomy. Main failures are wrong local claims and answer arithmetic errors; syntax/timeouts were not the limiting issue. At1000,108/200 IID examples and280/300 OOD examples contain reference local contexts absent from the training subset. Carry signatures are unseen for59/200 IID and300/300 OOD. The latter includes the structural length change; these are posthoc descriptive strata, not independently pre-reserved carry-only holdouts.','', '## Sanity and interpretive references','', 'The final supervised representation memorized n10, all45 canonical1x1 problems and a mixed100 training set at100% in diagnostics. Mixed100 validation reached3% answer-only and18% B; local claim accuracy62.47%, carry label accuracy82.60%. C n10 same-set accuracy was0% with incomplete accepted experience; it did not receive complete trajectories. This separates fitting ability from generalization and exploration coverage.','', '| Historical MLP on fresh final dataset at1000 | IID mean±SD | OOD mean±SD |','|---|---:|---:|']
 for c in names:
  t=next(r for r in history if r['condition']==c and r['split']=='test');o=next(r for r in history if r['condition']==c and r['split']=='ood_test');lines.append(f'|{names[c]}|{100*t["accuracy_mean"]:.3f}% ± {100*t["accuracy_std"]:.3f}|{100*o["accuracy_mean"]:.3f}% ± {100*o["accuracy_std"]:.3f}|')
 lines+=['','The original phase-4 dataset remains separate: its OOD accuracy was0% across all primary runs. Different sampled datasets can change rare correct counts. Larger final heads/categorical features/active losses/update budgets/pretrained features changed together, so gains over the MLP do not isolate pretraining. Deterministic execution scored100% IID/OOD; operand memorization and the seeded uniform-integer random reference scored0%. The deterministic ceiling is an algorithm, not a learning/data-efficiency baseline.','', '## Claims','', '| Claim | Status | Evidence | Limits |','|---|---|---|---|']
 lines += [f'|{c["claim"]}|{c["status"]}|{c["evidence"]}|{c["limitations"]}|' for c in claims]
 lines+=['','Supported descriptive findings: under these tested unequal-supervision protocols, B/C have higher IID accuracy than answer-only, and B executes some verified OOD trajectories. These observations do not establish an independent Mindscape wrapper advantage; matched-information policy predictions are identical. Data-efficiency, replay-storage, dream usefulness and second-domain-transfer claims are not supported. Broader causal claims remain inconclusive.','',f'Artifact audit:{audit["check_count"]} actual checks passed, including nested training IDs, shared parameter count, no singleton forcing, proposal/result separation, posthoc judgments, hypothetical tags and matched-control prediction equality.','', '## Figures','']
 for filename in ['accuracy','ood_accuracy','groundedness','goal_success','trajectory_validity','data_efficiency','ablation_effects','errors','training_compute','inference_cost']:lines.append(f'- [{filename}](../experiments/final_smollm2_v1/plots/{filename}.svg)')
 Path('docs/final_results.md').write_text('\n'.join(lines)+'\n')
 SNAP.mkdir(exist_ok=False);(SNAP/'plots').mkdir()
 for f in ['protocol.json','aggregate.json','data_efficiency.json','ablations.json','statistics.json','failure_taxonomy.json','difficulty_failures.json','fairness_audit.json','costs.json','resource_totals.json','holdout_coverage.json','sanity.json','claims.json','summary.md','runs.jsonl']:shutil.copy2(ROOT/f,SNAP/f)
 for f in ['accuracy','ood_accuracy','groundedness','goal_success','trajectory_validity','data_efficiency','ablation_effects','errors','training_compute','inference_cost']:shutil.copy2(ROOT/'plots'/(f+'.svg'),SNAP/'plots'/(f+'.svg'))
 shutil.copy2(Path('results/final/historical_mlp_v1/aggregate.json'),SNAP/'historical_mlp_aggregate.json');shutil.copy2(Path('results/final/references_v1/references.json'),SNAP/'references.json')
 report=['# Final build completion report','', '## IMPLEMENTED','', 'Stronger frozen local backbone adaptation, categorical task representation, four regimes, procedural100-candidate execution, posthoc verification, working/episodic/concept memory, bounded dreams, generic environment protocol, immutable result roots, statistics/failures/ten figures and an evidence UI.','', '## AUDITED','',f'Historical encodings, targets, losses, optimization, splits, initialization/decoding, information and cost; executed sanity checks; final{audit["check_count"]}-check artifact audit.','', '## FIXES APPLIED','', 'Removed dummy policy-head losses and artificial skip/sign coupling in the final adapter; categorical numerical representation and a larger head; matched replay ordering/update budget; strict checkpoint identity/reload tests; separated real/hypothetical posthoc annotations and resource units. Historical code/results retained.','', '## MODELS USED','', 'Pinned Apache2.0 SmolLM2-135M-Instruct frozen transformer plus learned task heads; historical NumPy MLP; deterministic ceiling, operand memorization and random references.','', '## MODEL SIZES','', '134,515,008 frozen backbone +337,618 trainable head =134,852,626 parameters per final primary condition. Historical MLP8722; deterministic/memorization/random references0 neural parameters.','', '## TRAINING REGIMES','', 'Answer-only, structured answer-only, trajectory-supervised B, bounded binary-feedback/accepted-experience replay C. Same frozen backbone/head capacity; fixed1200 Adam updates/batch64. Labels and query amounts differ and are disclosed.','', '## DATASETS','', 'Fresh final claims dataset seed5151:1000train/100validation/200IID/300OOD. Train1x1/2x1/2x2; OOD3x2/3x3/4x2. Canonical identity leakage checks; old development/research datasets preserved.','', '## DATA BUDGETS','', '10,25,50,100,250,500,1000;2500/5000 deferred.','', '## SEEDS','', '0,1,2 for all primary condition/budget pairs and component controls.','', '## IID RESULTS','', 'At1000 mean±SD:A5.000%±0.866; structured5.333%±1.041; B41.500%±2.179; C19.167%±3.014.','', '## OOD RESULTS','', 'At1000:B6.111%±1.347; A/structured/C0%±0. All OOD figures remain separate from IID.','', '## DATA-EFFICIENCY RESULTS','', 'Every N*(0.8/0.9/0.95) and DER is not reached; no2×/5× measured efficiency claim.','', '## GROUNDEDNESS','', 'IID at1000:B41.500%±2.179; C19.167%±3.014; answer baselines0% by evidence-required protocol. OOD B6.111%±1.347; others0%.','', '## TRAJECTORY VALIDITY','', 'IID at1000:B41.500%±2.179; C19.167%±3.014; OOD B6.111%±1.347/C0%; baselinesN/A.','', '## GOAL SUCCESS','', 'Same numerical rates as groundedness in the measured final primary runs; below95% target.','', '## ABLATIONS','', 'Three seeds at50. No state:−3pp IID; C supervision contrast:−2.5pp IID; no real environment:0pp accuracy and−3pp grounded/goal by definition. Matched local policy, replay-store bypass, goal-flag removal and dream/no-dream:0pp accuracy. All OOD deltas0. ΔDER unavailable from a single budget.','', '## DREAM RESULTS','', 'Goal-directed tagged integer rollout demonstrated; multiplication depth2/branch3 adds calls but no measured accuracy/ground/goal change at50. No learned world model or utility claim.','', '## SECOND-VERTICAL STATUS','', 'Deferred learned second environment. Generic interface and simulator reuse demonstrated; full learned architecture transfer not established.','', '## HISTORICAL GPT/GEMINI REFERENCE STATUS','', 'Published GPT-4/Gemini GSM8K sources retained with prompting/training caveats. Direct multiplication comparison unsuitable; no GPT superiority claim.','', '## COMPUTE COST','',f'Main:90 trained heads/210 evaluations; training{cost["totals"]["training_seconds"]:.3f}s/evaluation{cost["totals"]["evaluation_seconds"]:.3f}s cached CPU;108,000 updates/6,912,000 sampled rows/379,153 feedback queries/303,924 inference-head calls;1,961,882 shared encoder tokens. Old-model/reference runs reported separately. No compute-efficiency superiority.','', '## FAILURE ANALYSIS','', '22,367 arithmetic errors;28,762 wrong-action outcomes;133 unsupported outcomes;1238 grounded correct outcomes across210 repeated-set evaluations. Other listed failure classes0. Grouped digit/carry/condition/budget/split tables and example-level failures retained.','', '## CLAIMS SUPPORTED','', 'Narrow descriptive regime findings: B/C higher IID than answer-only under the tested unequal-supervision protocols; B nonzero verified OOD. Supervised pipeline can memorize; artifact/evidence separation verified. No broad architectural superiority claim is marked supported.','', '## CLAIMS NOT SUPPORTED','', 'Threshold-based data efficiency, replay-storage contribution, dream usefulness, second learned-domain transfer. Accuracy/OOD/grounding/trajectory/state causal claims are inconclusive under the available controls.','', '## KNOWN LIMITATIONS','', 'Hand-designed decomposition; unequal labels/queries; frozen indexed-feature backbone; one dataset/domain; small seed count; no independently reserved carry-only split; evidence metric privileges trajectory emitters; warm/shared CPU cache; second-domain and full fine-tuning deferred.','', '## TEST COUNT','', '92 tests passed, preserving all86 previous tests and adding six final regressions. Editable install, real checkpoint CLI, generator, training/reload and analysis/audits executed. Browser checked baseline toggle, real failed step and plots.','', '## GIT STATUS','', 'Final release on main with clean tracked working tree; historical commits preserved. Results/caches ignored; committed summary/figures/demo retained.','', '## LATEST COMMIT','', 'Resolve the stable final release with `git rev-parse mindscape-final-study-v1`; protocol records training-source commit5cbda01. Release hash is provided in the completion message.','', '## FINAL REPOSITORY TREE','', '```text','mindscape/','├── README.md / pyproject.toml / Makefile','├── src/mindscape/','│   ├── core/ data/ environments/ verification/','│   ├── models/ training/ evaluation/','│   └── memory/ reasoning/ concepts/','├── configs/experiments/ [historical + final protocols]','├── datasets/generated/ [development_v1, research_v1, final_v1]','├── scripts/ [generation, training, evaluation, analysis, audit, freeze, demo]','├── tests/ [five suites,92 tests]','├── docs/ [architecture, protocol, results, conclusions, limits, reproduction]','├── experiments/ [historical snapshots, final_audit, final_smollm2_v1]','├── results/final/ [smollm2_v1, historical_mlp_v1, references_v1]','├── demo/ [index.html, screenshot.png]','└── work/ [ignored local runtime, pretrained weights, frozen-feature cache, logs]','```','', '[Detailed results](final_results.md) · [Reproduce](final_reproducibility.md) · [Limitations](limitations.md)','']
 Path('docs/final_report.md').write_text('\n'.join(report));print(SNAP)
if __name__=='__main__':main()
